package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class GroupMyFeedbackIntegrationTest {
 SubmissionFeedbackStoreIntegrationTest f;GroupMyFeedbackStore store;FeedbackRetractionStore markers;
 @BeforeEach void setup(){f=new SubmissionFeedbackStoreIntegrationTest();f.setup();store=new GroupMyFeedbackStore(f.f.f.source,new GroupStore(f.f.f.source,Clock.systemUTC()));markers=new FeedbackRetractionStore(f.f.f.source,f.f.parent.store,f.f.store,Clock.systemUTC());}
 GroupMyFeedbackStore.Page list(String filter,UUID after,int limit){return store.list(f.f.group,f.f.space,f.f.author,after,limit,filter);}
 GroupMyFeedbackStore.Row row(){return list("ALL",null,100).items().stream().filter(v->v.submissionId().equals(f.answer.submissionId())).findFirst().orElseThrow();}
 FeedbackRetractionStore.Retraction mark(long target,long expected,String state){return markers.change(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.f.owner,target,expected,new FeedbackRetractionInput(state,"PRIVATE marker reason"),f.f.f.trace);}
 UUID task(){var id=f.f.parent.create(f.f.f.key()).assignment().assignmentId();f.f.parent.store.state(f.f.group,f.f.space,f.f.study,id,f.f.f.owner,1,"OPEN",f.f.f.trace);return id;}
 @Test void absenceReadAndOwnScopeDoNotExposePeersOrCreateFeedback(){
  int events=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);for(String filter:GroupMyFeedbackStore.FILTERS)assertTrue(list(filter,null,20).items().isEmpty());assertNull(f.get(f.f.author,false).feedback());assertEquals(events,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));f.change(0,1,"MY PRIVATE FEEDBACK");
  UUID peer=f.f.f.ids.next();for(UUID actor:List.of(peer,f.f.f.owner)){var sub=f.f.store.submit(f.f.group,f.f.space,f.f.study,f.f.assignment,actor,0,2,f.f.f.key(),"PRIVATE OTHER ANSWER",f.f.f.trace).submission();f.store.change(f.f.group,f.f.space,f.f.study,f.f.assignment,sub.submissionId(),f.f.f.owner,0,new SubmissionFeedbackInput("PRIVATE OTHER FEEDBACK",1,2),f.f.f.trace);assertEquals(sub.submissionId(),store.list(f.f.group,f.f.space,actor,null,20,"ALL").items().getFirst().submissionId());}
  UUID absent=task();f.f.store.submit(f.f.group,f.f.space,f.f.study,absent,f.f.author,0,2,f.f.f.key(),"NO COMMENT",f.f.f.trace);assertEquals(1,list("ALL",null,20).items().size());var json=tools.jackson.databind.json.JsonMapper.builder().build().valueToTree(row());assertEquals(15,json.size());for(String key:List.of("authorId","content","reason","score","reviewerId","snapshot","feedbackId"))assertFalse(json.has(key));assertEquals("CURRENT",row().feedbackStatus());assertTrue(store.list(f.f.group,f.f.space,f.f.f.ids.next(),null,20,"ALL").items().isEmpty());
 }
 @Test void resubmissionKeepsPriorOpinionAndRetractedFilterIncludesOldAnswer(){
  f.change(0,1,"Original feedback");assertEquals("CURRENT",row().feedbackStatus());f.f.submit(f.f.f.key(),1,2,"New answer");assertEquals("OUTDATED",row().feedbackStatus());assertEquals(1L,row().feedbackSubmissionVersion());mark(1,0,"RETRACTED");assertEquals("OUTDATED",row().feedbackStatus());assertEquals("RETRACTED",row().feedbackRetractionState());assertEquals(1,list("OUTDATED",null,20).items().size());assertEquals(1,list("RETRACTED",null,20).items().size());assertTrue(list("CURRENT",null,20).items().isEmpty());f.change(1,2,"Original feedback");assertEquals("CURRENT",row().feedbackStatus());assertEquals(2L,row().feedbackVersion());assertEquals(2L,row().feedbackSubmissionVersion());assertEquals("NONE",row().feedbackRetractionState());assertTrue(list("RETRACTED",null,20).items().isEmpty());
 }
 @Test void latestFeedbackVersionAloneDeterminesCurrentMarkerAndRestoration(){
  f.change(0,1,"First");mark(1,0,"RETRACTED");assertEquals("RETRACTED",row().feedbackStatus());mark(1,1,"RESTORED");assertEquals("CURRENT",row().feedbackStatus());assertEquals("RESTORED",row().feedbackRetractionState());f.change(1,1,"New text");mark(1,2,"RETRACTED");assertEquals("CURRENT",row().feedbackStatus());assertEquals("NONE",row().feedbackRetractionState());assertNull(row().retractionVersion());mark(2,0,"RETRACTED");assertEquals("RETRACTED",row().feedbackStatus());assertEquals(1,list("RETRACTED",null,20).items().size());mark(2,1,"RESTORED");assertEquals("CURRENT",row().feedbackStatus());assertEquals(2L,row().retractionVersion());
 }
 @Test void unknownMarkerFailsClosedInsteadOfEndorsingCurrentOpinion(){
  f.change(0,1,"PRIVATE feedback");var marker=mark(1,0,"RETRACTED");String saved=f.f.f.jdbc.queryForObject("SELECT snapshot::text FROM feedback_retraction WHERE retraction_id=?",String.class,marker.retractionId());try{for(String expression:List.of("snapshot-'state'","jsonb_set(snapshot,'{state}','\"INVALID\"')")){f.f.f.jdbc.update("UPDATE feedback_retraction SET snapshot="+expression+" WHERE retraction_id=?",marker.retractionId());assertEquals("UNAVAILABLE",row().feedbackStatus());assertEquals("UNKNOWN",row().feedbackRetractionState());assertTrue(list("CURRENT",null,20).items().isEmpty());assertTrue(list("RETRACTED",null,20).items().isEmpty());assertEquals(1,list("UNAVAILABLE",null,20).items().size());}}finally{f.f.f.jdbc.update("UPDATE feedback_retraction SET snapshot=?::jsonb WHERE retraction_id=?",saved,marker.retractionId());}
 }
 @Test void keysetFiltersBeforeLimitAcrossOwnAssignments(){
  f.change(0,1,"First");for(int n=0;n<10;n++){UUID assignment=task();var sub=f.f.store.submit(f.f.group,f.f.space,f.f.study,assignment,f.f.author,0,2,f.f.f.key(),"ANSWER",f.f.f.trace).submission();f.store.change(f.f.group,f.f.space,f.f.study,assignment,sub.submissionId(),f.f.f.owner,0,new SubmissionFeedbackInput("COMMENT",1,2),f.f.f.trace);if(n%2==0)f.f.store.submit(f.f.group,f.f.space,f.f.study,assignment,f.f.author,1,2,f.f.f.key(),"NEW ANSWER",f.f.f.trace);}
  assertEquals(11,list("ALL",null,100).items().size());assertEquals(6,list("CURRENT",null,100).items().size());assertEquals(5,list("OUTDATED",null,100).items().size());var seen=new ArrayList<UUID>();UUID after=null;do{var p=list("CURRENT",after,2);seen.addAll(p.items().stream().map(GroupMyFeedbackStore.Row::submissionId).toList());after=p.nextAfter();}while(after!=null);assertEquals(list("CURRENT",null,100).items().stream().map(GroupMyFeedbackStore.Row::submissionId).toList(),seen);assertEquals(6,new HashSet<>(seen).size());
 }
 @Test void currentSharedLabelsOriginalInstructionsAndGroupScopeStaySeparate(){
  f.change(0,1,"Original");f.f.parent.store.metadata(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,2,"New <script> title","New instructions",f.f.f.trace);assertEquals("New <script> title",row().assignmentTitle());assertEquals(2,row().assignmentVersion());assertEquals(2,f.get(f.f.author,false).feedback().assignmentVersion());f.status(404,()->store.list(f.f.f.ids.next(),f.f.space,f.f.author,null,20,"ALL"));f.status(404,()->store.list(f.f.group,f.f.f.ids.next(),f.f.author,null,20,"ALL"));var groups=new GroupStore(f.f.f.source,Clock.systemUTC());var pending=groups.request(f.f.f.owner,f.f.f.key(),"Pending private Group","",f.f.f.trace);var space=f.f.f.ids.next();f.status(404,()->store.list(pending.groupId(),space,f.f.author,null,20,"ALL"));groups.activate(pending.groupId(),f.f.f.owner,space,f.f.f.trace);assertTrue(store.list(pending.groupId(),space,f.f.author,null,20,"ALL").items().isEmpty());for(int limit:List.of(0,101))f.status(400,()->list("ALL",null,limit));for(String filter:List.of("current","MISSING","REQUESTED","","CURRENT' OR TRUE--"))f.status(400,()->list(filter,null,20));
 }
 @Test void closedArchivedReadsKeepOriginalOpinionMarkerAndEventsUnchanged(){
  var feedback=f.change(0,1,"Original");var marker=mark(1,0,"RETRACTED");f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,2,"CLOSED",f.f.f.trace);f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,3,"RETIRED",f.f.f.trace);f.f.parent.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.f.owner,1,"RETIRED",f.f.f.trace);int events=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);for(String filter:GroupMyFeedbackStore.FILTERS)list(filter,null,20);assertEquals("RETRACTED",row().feedbackStatus());assertEquals(feedback,f.get(f.f.author,false).feedback());assertEquals(marker,markers.get(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.author,false,1).retraction());assertEquals(events,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));
 }
 @Test void concurrentAnswerAndFeedbackReadsShareOneStatementSnapshot()throws Exception{
  f.change(0,1,"Original");try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CyclicBarrier(2);var reader=pool.submit(()->{barrier.await();for(int n=0;n<30;n++){var v=row();assertTrue(v.feedbackSubmissionVersion()<=v.version());if(v.feedbackStatus().equals("CURRENT"))assertEquals(v.version(),v.feedbackSubmissionVersion());else assertEquals("OUTDATED",v.feedbackStatus());}return true;});var writer=pool.submit(()->{barrier.await();f.f.submit(f.f.f.key(),1,2,"New answer");return f.change(1,2,"New feedback");});assertTrue(reader.get(20,TimeUnit.SECONDS));assertEquals(2,writer.get(20,TimeUnit.SECONDS).version());assertEquals("CURRENT",row().feedbackStatus());}
 }

 UUID task(UUID study){var id=f.f.parent.store.create(f.f.group,f.f.space,study,f.f.f.owner,f.f.f.key(),"Shared task <script>","Instructions",f.f.f.trace).assignment().assignmentId();f.f.parent.store.state(f.f.group,f.f.space,study,id,f.f.f.owner,1,"OPEN",f.f.f.trace);return id;}
 SubmissionStore.Submission commented(UUID study,UUID assignment,boolean outdated){var answer=f.f.store.submit(f.f.group,f.f.space,study,assignment,f.f.author,0,2,f.f.f.key(),"PRIVATE ANSWER",f.f.f.trace).submission();f.store.change(f.f.group,f.f.space,study,assignment,answer.submissionId(),f.f.f.owner,0,new SubmissionFeedbackInput("PRIVATE COMMENT",1,2),f.f.f.trace);if(outdated)f.f.store.submit(f.f.group,f.f.space,study,assignment,f.f.author,1,2,f.f.f.key(),"NEW PRIVATE ANSWER",f.f.f.trace);return answer;}
 @Test void allStudiesCurrentLabelsOriginalBasisArchivesAndNoCourseEvents(){
  f.change(0,1,"ORIGINAL PRIVATE");var b=f.f.parent.parent.create(f.f.f.key()).study();UUID id=task(b.studyId());var answer=commented(b.studyId(),id,false);task(b.studyId());f.f.parent.parent.store.metadata(f.f.group,f.f.space,b.studyId(),f.f.f.owner,1,"Current B <script>","Current",f.f.f.trace);f.f.parent.store.metadata(f.f.group,f.f.space,b.studyId(),id,f.f.f.owner,2,"Current task","New instructions",f.f.f.trace);f.f.parent.parent.store.state(f.f.group,f.f.space,b.studyId(),f.f.f.owner,2,"RETIRED",f.f.f.trace);
  assertEquals(2,list("ALL",null,100).items().size());var v=list("ALL",null,100).items().stream().filter(x->x.submissionId().equals(answer.submissionId())).findFirst().orElseThrow();assertEquals(b.studyId(),v.studyId());assertEquals("Current B <script>",v.studyTitle());assertEquals("RETIRED",v.studyState());assertEquals("Current task",v.assignmentTitle());assertEquals(2,v.assignmentVersion());assertEquals("CURRENT",v.feedbackStatus());int events=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);for(String filter:GroupMyFeedbackStore.FILTERS)list(filter,null,100);assertEquals(events,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));assertEquals(0,f.f.f.jdbc.queryForObject("SELECT count(*) FROM group_course WHERE group_id=?",Integer.class,f.f.group));
 }
 @Test void filteredKeysetCrossesStudiesAndExactMarkersExcludePeerComments(){
  f.change(0,1,"FIRST");var b=f.f.parent.parent.create(f.f.f.key()).study();for(int n=0;n<12;n++){UUID st=n%2==0?f.f.study:b.studyId(),id=task(st);var answer=commented(st,id,n%3==0);if(n%3==0)markers.change(f.f.group,f.f.space,st,id,answer.submissionId(),f.f.f.owner,1,0,new FeedbackRetractionInput("RETRACTED","PRIVATE REASON"),f.f.f.trace);var peer=f.f.store.submit(f.f.group,f.f.space,st,id,f.f.f.ids.next(),0,2,f.f.f.key(),"PEER PRIVATE",f.f.f.trace).submission();f.store.change(f.f.group,f.f.space,st,id,peer.submissionId(),f.f.f.owner,0,new SubmissionFeedbackInput("PEER COMMENT",1,2),f.f.f.trace);}
  assertEquals(13,list("ALL",null,100).items().size());assertEquals(9,list("CURRENT",null,100).items().size());assertEquals(4,list("OUTDATED",null,100).items().size());assertEquals(4,list("RETRACTED",null,100).items().size());for(var row:list("RETRACTED",null,100).items())assertEquals("OUTDATED",row.feedbackStatus());var seen=new ArrayList<UUID>();UUID after=null;do{var p=list("CURRENT",after,2);seen.addAll(p.items().stream().map(GroupMyFeedbackStore.Row::submissionId).toList());after=p.nextAfter();}while(after!=null);assertEquals(list("CURRENT",null,100).items().stream().map(GroupMyFeedbackStore.Row::submissionId).toList(),seen);assertEquals(9,new HashSet<>(seen).size());
 }
 @Test void sameActorFeedbackInAnotherGroupCannotLeakAcrossGroupSpace(){
  f.change(0,1,"MY GROUP");var other=new SubmissionFeedbackStoreIntegrationTest();other.setup();var answer=other.f.store.submit(other.f.group,other.f.space,other.f.study,other.f.assignment,f.f.author,0,2,other.f.f.key(),"OTHER GROUP PRIVATE",other.f.f.trace).submission();other.store.change(other.f.group,other.f.space,other.f.study,other.f.assignment,answer.submissionId(),other.f.f.owner,0,new SubmissionFeedbackInput("OTHER GROUP PRIVATE COMMENT",1,2),other.f.f.trace);assertEquals(1,list("ALL",null,100).items().size());assertTrue(list("ALL",null,100).items().stream().noneMatch(v->v.studyId().equals(other.f.study)));f.status(404,()->store.list(f.f.group,other.f.space,f.f.author,null,20,"ALL"));f.status(404,()->store.list(other.f.group,f.f.space,f.f.author,null,20,"ALL"));
 }
}
